sys_ui_action.client_script_v2:
function onClick(g_form) {
    console.log('[ESC CLIENT] UI Action clicked successfully.');

    var openModal = function() {
        g_modal.showFields({
            title: 'Request Supervisor Assistance',
            size: 'lg',
            fields: [
                { type: 'string', name: 'help_requested', label: 'Help Requested', mandatory: true },
                { type: 'choice', name: 'supervisor_action', label: 'Supervisor Action', mandatory: true,
                  choices: [
                      { value: 'observe', displayValue: 'Observe' },
                      { value: 'monitor', displayValue: 'Monitor' },
                      { value: 'coach', displayValue: 'Coach' },
                      { value: 'barge_in', displayValue: 'Barge In' }
                  ]
                },
                { type: 'string', name: 'supervisor_group_display', label: 'Supervisor Group', value: 'Contact Centre Supervisors', disabled: true }
            ]
        }).then(function(result) {
            console.log('[ESC CLIENT] Modal submitted. Extracting fields cleanly...');

            var getVal = function(name, defaultValue) {
                if (result && result.updatedFields) {
                    var field = result.updatedFields.filter(function(f) { return f.name === name; })[0];
                    if (field) return field.value;
                }
                return defaultValue || '';
            };

            var helpText = getVal('help_requested', '');
            var actionType = getVal('supervisor_action', 'observe');
            var interactionSysId = g_form.getUniqueValue();
            var defaultGroupSysId = 'bc4fe9f9cf8a431009d5b6734d851c73'; 

            var ga = new GlideAjax('x_snc_pab_ee_tkit.EscRecordCreation');
            ga.addParam('sysparm_name', 'executeEscalationSubflow');
            ga.addParam('sysparm_interaction', interactionSysId);
            ga.addParam('sysparm_help_requested', helpText);
            ga.addParam('sysparm_supervisor_action', actionType);
            ga.addParam('sysparm_supervisor_group', defaultGroupSysId);

            ga.getXMLAnswer(function(response) {
                g_form.clearMessages();
                console.log('[ESC CLIENT] Server tracking package returned: ' + response);

                try {
                    if (!response) {
                        showStaticAutoDismissBanner('Received empty response payload from the server.', true);
                        return;
                    }

                    var parsed = JSON.parse(response);
                    if (parsed && parsed.status === 'success') {
                        var baseMsg = parsed.notes ? 'Escalation processed: ' + parsed.notes : 'Escalation activity created successfully.';
                        showStaticAutoDismissBanner(baseMsg, false);
                        g_form.reload();
                    } else {
                        showStaticAutoDismissBanner(parsed.message || 'Escalation subflow tracking failure.', true);
                    }
                } catch(err) {
                    showStaticAutoDismissBanner('An error occurred while processing the escalation pipeline stream.', true);
                }
            });
        });
    };

    // Helper function to render a solid, non-flashing banner that auto-dismisses after 5 seconds
    function showStaticAutoDismissBanner(baseMessage, isError) {
        g_form.clearMessages();

        // Append a clean suffix so agents know it will close on its own
        var fullMessage = baseMessage + ' (Notification clearing in 5s)';

        if (isError) {
            g_form.addErrorMessage(fullMessage);
        } else {
            g_form.addInfoMessage(fullMessage);
        }

        // Quietly clear the message once after 5000ms without intermediate rendering updates
        setTimeout(function() {
            if (typeof g_form !== 'undefined' && g_form.clearMessages) {
                g_form.clearMessages();
            }
        }, 5000);
    }

    openModal();
}
